From 7defe2a21a4eedda76e83f22e96372309f570aeb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 04:46:22 +0100
Subject: [PATCH] containmentlayoutmanager: apply size hints skipped in edit
 mode

A widget dropped on the desktop while hovered is in edit mode, and the
layout ignored the size hints it got then, leaving it too short for its
contents. Apply them when leaving edit mode unless the user resized it.

BUG: 524502
---
 .../containmentlayoutmanager/itemcontainer.cpp    | 15 ++++++++++++++-
 .../containmentlayoutmanager/itemcontainer.h      |  3 +++
 2 files changed, 17 insertions(+), 1 deletion(-)

diff --git a/components/containmentlayoutmanager/itemcontainer.cpp b/components/containmentlayoutmanager/itemcontainer.cpp
index e23678ef37..9aab1020d8 100644
--- a/components/containmentlayoutmanager/itemcontainer.cpp
+++ b/components/containmentlayoutmanager/itemcontainer.cpp
@@ -53,7 +53,13 @@ ItemContainer::ItemContainer(QQuickItem *parent)
     m_sizeHintAdjustTimer->setSingleShot(true);
     m_sizeHintAdjustTimer->setInterval(0);

-    connect(m_sizeHintAdjustTimer, &QTimer::timeout, this, &ItemContainer::sizeHintsChanged);
+    connect(m_sizeHintAdjustTimer, &QTimer::timeout, this, [this]() {
+        // The layout ignores size hints in edit mode: apply them when leaving it, unless the user resized the item
+        if (m_editMode && !m_sizeWhenSizeHintsSkipped) {
+            m_sizeWhenSizeHintsSkipped = size();
+        }
+        Q_EMIT sizeHintsChanged();
+    });
 }

 ItemContainer::~ItemContainer()
@@ -142,6 +148,13 @@ void ItemContainer::setEditMode(bool editMode)
     setConfigOverlayVisible(editMode);

     Q_EMIT editModeChanged(editMode);
+
+    if (!editMode && m_sizeWhenSizeHintsSkipped) {
+        if (*m_sizeWhenSizeHintsSkipped == size()) {
+            m_sizeHintAdjustTimer->start();
+        }
+        m_sizeWhenSizeHintsSkipped.reset();
+    }
 }

 ItemContainer::EditModeCondition ItemContainer::editModeCondition() const
diff --git a/components/containmentlayoutmanager/itemcontainer.h b/components/containmentlayoutmanager/itemcontainer.h
index 2aecb2c72b..e66a053277 100644
--- a/components/containmentlayoutmanager/itemcontainer.h
+++ b/components/containmentlayoutmanager/itemcontainer.h
@@ -10,6 +10,8 @@
 #include <QQmlParserStatus>
 #include <QQuickItem>

+#include <optional>
+
 #include "appletslayout.h"

 class QTimer;
@@ -228,6 +230,7 @@ private:
     QObject *m_layoutAttached = nullptr;
     EditModeCondition m_editModeCondition = Manual;
     QSizeF m_initialSize;
+    std::optional<QSizeF> m_sizeWhenSizeHintsSkipped;

     QUrl m_configOverlaySource;
     ConfigOverlay *m_configOverlay = nullptr;
-- 
